/// Returns a broadcast [Stream] of events from the `downloads` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<DownloadsSnapshot> downloads({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel downloadsChannel = EventChannel(
    'dev.flutter.pigeon.grabby.FetchrEvents.downloads$instanceName',
    pigeonMethodCodec,
  );
  return downloadsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as DownloadsSnapshot;
  });
}
